numbers = [2, 5, 8, 12, 16, 23, 38, 45, 56, 72]
target = 23
low, high = 0, len(numbers) - 1
index = -1

while low <= high:
    mid = (low + high) // 2
    if numbers[mid] == target:
        index = mid
        break
    elif numbers[mid] < target:
        low = mid + 1
    else:
        high = mid - 1

if index != -1:
    print(f"Found {target} at index {index}")
else:
    print(f"{target} not found")
